import { useState } from 'react';
import { Button } from '@tale-ui/react/button';
import { createToastQueue, ToastRegion } from '@tale-ui/react/toast';

export function AsyncFeedback({ save }: { save: () => Promise<void> }) {
  const [isSaving, setIsSaving] = useState(false);
  const [queue] = useState(() => createToastQueue({ maxVisibleToasts: 3 }));

  async function handleSave() {
    setIsSaving(true);

    try {
      await save();
      queue.add({
        title: 'Changes saved',
        description: 'Your preferences are up to date.',
        variant: 'success',
      });
    } catch {
      queue.add(
        {
          title: 'Changes not saved',
          description: 'Check your connection and try again.',
          variant: 'danger',
        },
        { timeout: 0 },
      );
    } finally {
      setIsSaving(false);
    }
  }

  return (
    <>
      <Button isPending={isSaving} onPress={() => void handleSave()}>
        Save changes
      </Button>
      <ToastRegion queue={queue} />
    </>
  );
}
